    implementation: guidance, accessibility, states,
    responsive: 'Reflow at 500px into a single column. Preserve reading order and 44px action targets. Use content-driven widths.',
    codeType: 'html-css', specimenBehavior: 'Static visual specimen with native HTML controls. Application events and persistence must be connected by the integrator.',
