function pack(id,title,summary,tags,patternIds,colors,principles,source) {
  const display = ['precise-workspace','public-service','financial-clarity','daily-companion'].includes(id) ? 'Inter, system-ui, sans-serif' : 'Instrument Serif, Georgia, serif';
  return {id,title,summary,tags,patterns:patternIds,tokens:{...baseTokens,typography:{...baseTokens.typography,display},colors},principles,
    sourceName:sources[source][0],sourceUrl:sources[source][1],
    provenance:'Original authored direction informed by a linked public reference. Tokens are independent design choices.',
    acceptance:['All foreground/background pairs used for body text meet 4.5:1 contrast.','Keyboard focus is visible and follows reading order.','Loading, empty, error and success states are implemented.','Mobile layouts reflow without horizontal page scrolling.','Content names the user’s actual product, audience and task.'],
  };
}
