// Each enhanced study runs in its own document. Demo actions stay in that document.
const localBehaviors = {
  'calm-onboarding': `const input=document.querySelector('input');const button=document.querySelector('button');button.addEventListener('click',()=>{if(!input.value.trim()){input.setCustomValidity('Give your notebook a name.');input.reportValidity();return;}document.querySelector('.card').innerHTML='<h2></h2><p>Your notebook is ready. Write your first note.</p><label for="first-note">First note</label><textarea id="first-note" rows="4"></textarea><button type="button">Save note</button><p role="status"></p>';document.querySelector('h2').textContent=input.value.trim();document.querySelector('button').onclick=()=>{document.querySelector('[role=status]').textContent=document.querySelector('textarea').value.trim()?'Note saved in this demo.':'Write a note before saving.';};});input.addEventListener('input',()=>input.setCustomValidity(''));`,
  'calm-empty-state': `document.querySelector('button').onclick=()=>{document.querySelector('.card').innerHTML='<h2>Your first idea</h2><label for="new-note">Note</label><textarea id="new-note" rows="5"></textarea><button type="button">Save note</button><p role="status"></p>';document.querySelector('textarea').focus();document.querySelector('button').onclick=()=>{const value=document.querySelector('textarea').value.trim();document.querySelector('[role=status]').textContent=value?'Your note is saved in this demo.':'Write an idea before saving.';};};`,
  'meeting-note': `const card=document.querySelector('.card');const status=document.createElement('p');status.setAttribute('role','status');card.append(status);document.querySelectorAll('input').forEach(input=>input.addEventListener('change',()=>{const all=[...document.querySelectorAll('input')];status.textContent=all.filter(x=>x.checked).length+' of '+all.length+' actions completed in this demo.';}));`,
  'command-launcher': `const query=document.querySelector('input');const rows=[...document.querySelectorAll('.row')];const status=document.createElement('p');status.setAttribute('role','status');query.after(status);function filter(){let count=0;rows.forEach(row=>{row.hidden=!row.textContent.toLowerCase().includes(query.value.toLowerCase());row.style.display=row.hidden?'none':'';if(!row.hidden)count++;});status.textContent=count+' commands';}query.oninput=filter;query.onkeydown=event=>{const buttons=rows.filter(row=>!row.hidden).map(row=>row.querySelector('button'));if(event.key==='ArrowDown'&&buttons.length){event.preventDefault();buttons[0].focus();}if(event.key==='Enter'&&buttons.length)buttons[0].click();};rows.forEach((row,index)=>{const button=row.querySelector('button');button.onclick=()=>{status.textContent='Selected '+button.textContent+'. Connect this command to your application action.';};button.onkeydown=event=>{const buttons=rows.filter(r=>!r.hidden).map(r=>r.querySelector('button'));const at=buttons.indexOf(button);if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();buttons[(at+(event.key==='ArrowDown'?1:buttons.length-1))%buttons.length].focus();}if(event.key==='Escape')query.focus();};});filter();`,
  'issue-list': `const table=document.querySelector('table');const search=document.createElement('input');search.type='search';search.placeholder='Filter issues';search.setAttribute('aria-label','Filter issues');table.before(search);const rows=[...table.tBodies[0].rows];search.oninput=()=>rows.forEach(row=>{row.hidden=!row.textContent.toLowerCase().includes(search.value.toLowerCase());});document.querySelector('button').onclick=()=>{const form=document.createElement('form');form.className='stack';form.innerHTML='<label for="issue-title">Issue title</label><input id="issue-title" required><button>Create issue</button>';search.before(form);form.querySelector('input').focus();form.onsubmit=event=>{event.preventDefault();const row=table.tBodies[0].insertRow();[form.querySelector('input').value,'Planned','You'].forEach(value=>row.insertCell().textContent=value);rows.push(row);form.remove();};};`,
  'project-progress': `const button=document.createElement('button');button.type='button';button.className='secondary';button.textContent='Complete next task';const card=document.querySelector('.card');card.append(button);let done=18;button.onclick=()=>{done=Math.min(done+1,24);document.querySelector('.muted').textContent=done+' of 24 launch tasks completed';const percent=Math.round(done/24*100);document.querySelector('[role=progressbar]').setAttribute('aria-valuenow',percent);document.querySelector('.progress span').style.width=percent+'%';if(done===24){document.querySelector('.tag').textContent='Complete';button.disabled=true;button.textContent='All tasks complete';}};`,
  'activity-thread': `const input=document.querySelector('textarea');const button=document.createElement('button');button.textContent='Post update';button.type='button';input.after(button);button.onclick=()=>{if(!input.value.trim()){input.setCustomValidity('Write an update first.');input.reportValidity();return;}const li=document.createElement('li');const name=document.createElement('strong');name.textContent='You ';li.append(name,document.createTextNode(input.value.trim()));document.querySelector('ol').prepend(li);input.value='';};input.oninput=()=>input.setCustomValidity('');`,
  'civic-form': `const form=document.querySelector('form');form.onsubmit=event=>{event.preventDefault();const email=form.querySelector('input').value;form.innerHTML='<h2>Check your email address</h2><p></p><button type="button" class="secondary">Change email</button><button type="button">Confirm request</button>';form.querySelector('p').textContent=email;form.querySelector('.secondary').onclick=()=>location.reload();form.querySelector('button:last-child').onclick=()=>{form.innerHTML='<h2>Demo request complete</h2><p>Your email was validated. Connect a backend to send a real confirmation.</p>';};};`,
  'error-recovery': `const field=document.querySelector('input');field.required=true;const button=document.createElement('button');button.type='button';button.textContent='Check address';field.parentElement.append(button);button.onclick=()=>{const valid=field.checkValidity();if(valid){field.removeAttribute('aria-invalid');document.querySelector('[role=alert]').innerHTML='<h2>Email address accepted</h2><p>The address format is valid in this demo.</p>';document.querySelector('#recovery-error').hidden=true;}else{field.setAttribute('aria-invalid','true');field.reportValidity();}};`,
  'review-answers': `const links=[...document.querySelectorAll('dd a')];links.forEach(link=>link.onclick=event=>{event.preventDefault();const answer=link.parentElement.previousElementSibling;const previous=answer.textContent;answer.textContent='';const input=document.createElement('input');input.value=previous;input.setAttribute('aria-label','Edit '+link.parentElement.parentElement.querySelector('dt').textContent);answer.append(input);const save=document.createElement('button');save.type='button';save.textContent='Save';answer.append(save);save.onclick=()=>{answer.textContent=input.value.trim()||previous;};input.focus();});document.querySelector('button').onclick=()=>{document.querySelector('.card').innerHTML='<h2>Demo request submitted</h2><p>Reference DEMO-2048. Your answers passed the review step.</p>';};`,
  'commerce-product': `const finish=document.querySelector('select');const button=document.querySelector('button');const status=document.createElement('p');status.setAttribute('role','status');button.after(status);let count=0;button.onclick=()=>{count++;status.textContent=count+' '+(count===1?'vessel':'vessels')+' in your demo bag. Finish '+finish.value+'.';};`,
  'order-summary': `const button=document.querySelector('button');button.onclick=()=>{const box=document.createElement('div');box.className='stack';box.innerHTML='<h3>Payment handoff</h3><p>Total $57.84 USD. Integrate a hosted payment provider to complete a real purchase.</p><button type="button" class="secondary">Return to order</button>';button.hidden=true;button.after(box);box.querySelector('button').onclick=()=>{box.remove();button.hidden=false;button.focus();};};`,
  'plan-comparison': `const toolbar=document.createElement('div');toolbar.className='toolbar';toolbar.style.marginBottom='20px';toolbar.innerHTML='<button type="button" aria-pressed="true">Monthly</button><button class="secondary" type="button" aria-pressed="false">Annual</button>';document.querySelector('.grid').before(toolbar);const cards=[...document.querySelectorAll('.card')];const buttons=[...toolbar.querySelectorAll('button')];buttons.forEach((button,index)=>button.onclick=()=>{buttons.forEach((b,i)=>{b.setAttribute('aria-pressed',String(i===index));b.classList.toggle('secondary',i!==index);});cards.forEach((card,i)=>{card.querySelector('.price').innerHTML=(index?['$120','$290'][i]:['$12','$29'][i])+'<small>/'+(index?'year':'month')+'</small>';});});cards.forEach(card=>card.querySelector('button').onclick=()=>{let status=card.querySelector('[role=status]');if(!status){status=document.createElement('p');status.setAttribute('role','status');card.append(status);}status.textContent=card.querySelector('h2').textContent+' selected. Billing '+(buttons[1].getAttribute('aria-pressed')==='true'?'annually.':'monthly.');});`,
  'cart-edit': `const card=document.querySelector('.card');const quantity=document.querySelector('input');const price=card.querySelector('strong');const remove=document.querySelector('.secondary');quantity.oninput=()=>{if(quantity.checkValidity())price.textContent='$'+(Number(quantity.value)*48).toFixed(2);};remove.onclick=()=>{card.querySelectorAll('.row').forEach(row=>row.hidden=true);const status=document.createElement('p');status.textContent='Your bag is empty.';const undo=document.createElement('button');undo.type='button';undo.textContent='Undo removal';remove.parentElement.after(status,undo);const checkout=card.querySelector(':scope > button:last-child');checkout.disabled=true;undo.onclick=()=>{card.querySelectorAll('.row').forEach(row=>row.hidden=false);status.remove();undo.remove();checkout.disabled=false;};};card.querySelector(':scope > button:last-child').onclick=()=>{quantity.reportValidity();if(quantity.checkValidity()){const p=document.createElement('p');p.setAttribute('role','status');p.textContent='Demo subtotal $'+(Number(quantity.value)*48).toFixed(2)+'. Shipping and tax are calculated at checkout.';card.append(p);}};`,
  'reference-collection': `const stack=document.querySelector('.stack');const input=document.createElement('input');input.type='search';input.placeholder='Search onboarding studies';input.setAttribute('aria-label','Search studies');stack.before(input);const items=[...stack.querySelectorAll('article')];input.oninput=()=>{let count=0;items.forEach(item=>{item.hidden=!item.textContent.toLowerCase().includes(input.value.toLowerCase());if(!item.hidden)count++;});document.querySelector('.tag').textContent=count+' studies';};`,
  'transaction-list': `const table=document.querySelector('table');const select=document.createElement('select');select.setAttribute('aria-label','Filter transaction status');select.innerHTML='<option>All statuses</option><option>Settled</option><option>Pending</option><option>Refunded</option>';table.before(select);select.onchange=()=>[...table.tBodies[0].rows].forEach(row=>row.hidden=select.value!=='All statuses'&&row.cells[3].textContent!==select.value);`,
  'budget-allocation': `const article=document.querySelector('article');const form=document.createElement('form');form.className='stack';form.innerHTML='<label for="expense">Record a demo expense in dollars</label><input id="expense" type="number" min="1" max="100000" value="1200" required><button>Record expense</button><p role="status"></p>';article.append(form);let spent=6400;form.onsubmit=event=>{event.preventDefault();spent+=Number(form.querySelector('input').value);article.querySelector('.price').textContent='$'+spent.toLocaleString('en-US');article.querySelector('p strong').textContent=spent<=10000?'$'+(10000-spent).toLocaleString('en-US')+' available':'$'+(spent-10000).toLocaleString('en-US')+' over budget';const percent=Math.min(100,Math.round(spent/100));article.querySelector('[role=progressbar]').setAttribute('aria-valuenow',percent);article.querySelector('.progress span').style.width=percent+'%';form.querySelector('[role=status]').textContent='Expense recorded in the demo ledger.';};`,
  'destructive-confirmation': `const section=document.querySelector('.card');const buttons=[...section.querySelectorAll('button')];buttons[0].onclick=()=>{section.innerHTML='<h2>Project kept active</h2><p>No archive change was made in this demo.</p><button type="button">Review again</button>';section.querySelector('button').onclick=()=>location.reload();};buttons[1].onclick=()=>{section.innerHTML='<h2>Project archived in this demo</h2><p>Notes and activity remain available.</p><button type="button" class="secondary">Undo archive</button>';section.querySelector('button').onclick=()=>location.reload();};`,
  'mobile-onboarding': `const phone=document.querySelector('.phone');const input=phone.querySelector('input');const buttons=[...phone.querySelectorAll('button')];function next(skipped){const value=input.value;phone.innerHTML='<small>Step 2 of 3</small><h2>Choose your first reflection</h2><p></p><label for="reflection">What would you like to notice?</label><input id="reflection" placeholder="A small thing that went well"><button type="button">Finish setup</button>';phone.querySelector('p').textContent=skipped?'You can choose a reminder later.':'Reminder preference '+value+' saved for this demo.';phone.querySelector('button').onclick=()=>{phone.innerHTML='<small>Step 3 of 3</small><h2>You’re ready</h2><p>Your demo routine has been created.</p>';};}buttons[0].onclick=()=>next(false);buttons[1].onclick=()=>next(true);`,
  'permission-primer': `const phone=document.querySelector('.phone');const buttons=[...phone.querySelectorAll('button')];buttons[0].onclick=()=>{phone.innerHTML='<h2>Reminder preference saved</h2><p>This browser demo records your choice. The installed application should request its device notification permission here.</p>';};buttons[1].onclick=()=>{phone.innerHTML='<h2>Continue at your own pace</h2><p>Reminders are off for this demo.</p>';};`,
  'mobile-settings': `const phone=document.querySelector('.phone');const status=document.createElement('p');status.setAttribute('role','status');phone.append(status);phone.querySelectorAll('input,select').forEach(input=>input.onchange=()=>{status.textContent='Preference saved for this demo session.';});phone.querySelector('select').addEventListener('change',event=>{phone.style.fontSize=event.target.selectedIndex===2?'22px':event.target.selectedIndex===1?'19px':'';});`,
  'mobile-daily-log': `const input=document.querySelector('textarea');const button=document.querySelector('button');const status=document.createElement('p');status.setAttribute('role','status');button.after(status);button.onclick=()=>{if(!input.value.trim()){input.setCustomValidity('Write one thought before saving.');input.reportValidity();return;}status.textContent='Today’s note is saved in this demo session.';button.textContent='Save changes';};input.oninput=()=>input.setCustomValidity('');document.querySelector('a').onclick=event=>{event.preventDefault();status.textContent='This demo contains only today’s note.';};`,
  'studio-inquiry': `const form=document.querySelector('form');form.onsubmit=event=>{event.preventDefault();form.innerHTML='<h2>Demo inquiry received</h2><p>Your form passed validation. Connect your inquiry endpoint to send this to the studio.</p>';};`,
};
