const packTheme = ['calm','precision','civic','commerce','editorial','finance','mobile','studio'];
for (const [index, pack] of packs.entries()) {
  for (const id of pack.patterns) {
    const item = patterns.find(candidate => candidate.id === id);
    item.css += '\n' + studyStyles[packTheme[index]];
    if (localBehaviors[id]) {
      item.js = localBehaviors[id];
      item.specimenBehavior = 'Working local browser interaction. Demo state lasts for the document session. Payment, account, notifications and message delivery require the stated application integration.';
    }
  }
}

const focusedSources = {
  'error-recovery': ['GOV.UK error summary', 'https://design-system.service.gov.uk/components/error-summary/'],
  'review-answers': ['GOV.UK check answers pattern', 'https://design-system.service.gov.uk/patterns/check-answers/'],
  'completion-receipt': ['GOV.UK confirmation pages', 'https://design-system.service.gov.uk/patterns/confirmation-pages/'],
  'order-summary': ['Stripe Checkout customization', 'https://docs.stripe.com/payments/checkout/customization'],
  'studio-case-study': ['Instrument — Nike Digital Design System', 'https://www.instrument.com/work/nike-digital-design-system'],
  'studio-service': ['Instrument services', 'https://www.instrument.com/services'],
};
for (const [id, [sourceName, sourceUrl]] of Object.entries(focusedSources)) {
  Object.assign(patterns.find(item => item.id === id), {sourceName, sourceUrl});
}
